'use strict';
/**
 * The class tab's round card while a round is paused: jg.round.t_paused ("{done} of {total} played. Continue another
 * day.") with the same numbers as the paused round's own screen (positions only, no name). Every other state (not
 * started, the window not open yet, running, resumed, closed) renders the card byte-identical to the code before this
 * line existed: the snapshots in __snapshots__/class-round-paused-card.test.js.snap were written by this file on the
 * unchanged code and are never regenerated by the change.
 * Real round service, card template, report route, tokens; faked: Supabase (in-memory), the event logger, the
 * hashed-key module, WhatsApp and the ledger.
 */
jest.mock('../../../shared/config/supabase', () => ({}));
jest.mock('../../../shared/utils/logger', () => ({ logToFile: jest.fn(), logError: jest.fn(), logWarn: jest.fn() }));
jest.mock('../../../shared/utils/structured-logger', () => ({ logEvent: jest.fn(), getCurrentCorrelationId: () => null }));
jest.mock('../../../shared/utils/html-to-pdf', () => ({ htmlToPdf: jest.fn(async () => Buffer.from('%PDF-1.4 fake')) }));
jest.mock('../../../shared/services/whatsapp.service', () => ({ sendMessage: jest.fn(), sendTextMessage: jest.fn(), sendInteractiveMessage: jest.fn() }));
jest.mock('../../../shared/services/quiz/message-ledger', () => ({ record: jest.fn() }));
jest.mock('../../../shared/services/quiz/web-quiz-kid', () => ({
  kid: (id) => `kid(${String(id).slice(-2)})`, cls: (id) => `cls(${String(id).slice(-2)})`, envelope: (f) => ({ w: 's', ev_v: 2, kid_v: '2026', ...f }),
}));

const express = require('express');
const { makeFake } = require('./fake-supabase');
const { strictFrom } = require('./class-round-strict-fake');

const TEACHER = '11111111-1111-4111-8111-111111111111';
const CLASS = 'c0000000-0000-4000-8000-0000000000c1';
const SCHOOL = 'd0000000-0000-4000-8000-0000000000d1';
const ROUND = '0123456789abcdef';
const DAY = 86400000;
const N = 9;
const kid = (n) => `b0000000-0000-4000-8000-0000000000${String(n).padStart(2, '0')}`;
const nameOf = (n) => `Kid${n} Testwala`;
const ON = [
  { key: 'web_quiz_challenge', value: true }, { key: 'web_quiz_challenge_v2', value: true }, { key: 'web_quiz_class_round', value: true },
  { key: 'web_quiz_hub', value: true }, { key: 'web_quiz_events_v2', value: true },
];
const iso = (ms) => new Date(ms).toISOString();
const CARD_TOKEN = 'tok-fixed';

let DB;
function seed({ draw = {} } = {}) {
  const now = Date.now();
  DB = {
    app_settings: ON.map((s) => ({ ...s })),
    users: [{ id: TEACHER, preferred_language: 'en' }],
    quizzes: [], quiz_share_codes: [], student_lists: [], quiz_sessions: [], quiz_questions: [], quiz_answers: [],
    schools: [{ id: SCHOOL, name: 'School A', region: 'Sector One', is_active: true, is_probable_test: false }],
    classes: [{ id: CLASS, school_id: SCHOOL, grade_code: 'grade_3', section: 'B', is_active: true }],
    class_teachers: [{ id: 'ct1', class_id: CLASS, teacher_user_id: TEACHER, is_class_teacher: true, is_active: true }],
    students: Array.from({ length: N }, (_, i) => ({ id: kid(i + 1), student_name: nameOf(i + 1), is_active: true })),
    class_enrollments: Array.from({ length: N }, (_, i) => ({ id: `e${i}`, class_id: CLASS, student_id: kid(i + 1), roll_number: i + 1, is_active: true })),
    class_round_draws: [{ id: 'e0000000-0000-4000-8000-0000000000e1', round: ROUND, term_code: require('../../../shared/services/quiz/web-quiz-class-round-sampler').termCode(now),
      class_id: CLASS, stratum: 'Sector One|G23', N_h: 10, n_h: 2, p_incl: 0.2, seed: 7, weights_version: 'v1', roster_k: N,
      window_start: iso(now - 2 * DAY), window_end: iso(now + 26 * DAY), k_counted: 10, order_arm: 'round_first', week_start: null, week_end: null,
      drawn_at: iso(now - 9 * DAY), accepted_at: null, declined_at: null, started_at: null, ran_at: null, finished_at: null,
      children_present: null, children_played: null, state: null, ...draw }],
    child_identity: [],
    web_quiz_challenge_runs: [],
  };
  const fake = makeFake(DB);
  Object.assign(require('../../../shared/config/supabase'), { from: strictFrom(fake), rpc: fake.rpc });
}

let server; let base; let Token; let Round;
beforeEach(async () => {
  jest.resetModules();
  process.env.INTERNAL_API_KEY = 'test-key';
  delete process.env.WEB_QUIZ_TOKEN_SECRET;
  seed();
  Token = require('../../../shared/services/quiz/teacher-report-token');
  Round = require('../../../shared/services/quiz/web-quiz-class-round');
  const app = express();
  app.use('/api/internal/tr', require('../../../shared/routes/teacher-report-internal.routes'));
  await new Promise((r) => { server = app.listen(0, '127.0.0.1', r); });
  base = `http://127.0.0.1:${server.address().port}/api/internal/tr`;
});
afterEach(async () => { await new Promise((r) => server.close(r)); });

const tok = () => Token.signTeacherReport({ teacherId: TEACHER });
const get = (p) => fetch(`${base}${p}`, { headers: { 'x-api-key': 'test-key' }, redirect: 'manual' });
const post = (p, body = {}) => fetch(`${base}${p}`, { method: 'POST', headers: { 'x-api-key': 'test-key', 'content-type': 'application/json' }, body: JSON.stringify(body), redirect: 'manual' });
const draw = () => DB.class_round_draws[0];
const HOLD = { act: 'hold', hold: '700' };
const card = (lang) => Round.cardFor(TEACHER, { lang, token: CARD_TOKEN });
const cardOf = (html) => (/<section class="card cr-card"[\s\S]*?<\/section>/.exec(html) || [''])[0];
const PAUSED_EN = '3 of 9 played. Continue another day.';
const PAUSED_UR = '۹ میں سے ۳ بچوں نے کھیل لیا۔ کسی اور دن جاری رکھیں۔';

/** Start, play the first three positions through the real routes, then pause: 3 of 9 played. */
async function playThreeThenPause() {
  await Round.start(TEACHER, { rng: () => 0.3 });
  const order = draw().state.order.map((p) => p.id);
  for (let i = 0; i < 3; i += 1) {
    await post(`/round/${tok()}/next`, HOLD);
    await Round.childFinished(ROUND, order[i], `run-${i}`);
    await post(`/round/${tok()}/teacher`, HOLD);
  }
  expect((await post(`/round/${tok()}/pause`)).status).toBeLessThan(400);
  expect(draw().state.paused).toBe(true);
  return order;
}

describe('a paused round: the card says where it stopped', () => {
  test('3 of 9 played → the class tab card shows the EN line and the UR line, positions only', async () => {
    await playThreeThenPause();
    const en = cardOf(await (await get(`/page/${tok()}`)).text());
    expect(en).toContain(PAUSED_EN);
    const ur = cardOf(await (await get(`/page/${tok()}?lang=ur`)).text());
    expect(ur).toContain(PAUSED_UR);
    for (const html of [en, ur]) {
      expect(html).not.toMatch(/Testwala|Kid\d/);
      expect(html).not.toContain(ROUND);
      expect(html).not.toMatch(/b0000000-|c0000000-|e0000000-/);
    }
  });

  test('the numbers are the paused screen\'s own: done ticks and every position, absent included', async () => {
    await Round.start(TEACHER, { rng: () => 0.3 });
    const order = draw().state.order.map((p) => p.id);
    await post(`/round/${tok()}/absent`, { pos: '1' });
    await post(`/round/${tok()}/next`, HOLD);
    await Round.childFinished(ROUND, order[0], 'run-0');
    await post(`/round/${tok()}/teacher`, HOLD);
    await post(`/round/${tok()}/pause`);
    const screen = await (await get(`/round/${tok()}`)).text();
    expect(screen).toContain('1 of 9 done, 1 absent');
    expect(await card('en')).toContain('1 of 9 played. Continue another day.');
  });

  test('the line is the copy deck\'s value verbatim (EN and UR)', async () => {
    const d = require('../../../shared/config/copy.v2.json')['jg.round.t_paused'];
    await playThreeThenPause();
    expect(await card('en')).toContain(d.en.replace('{done}', '3').replace('{total}', '9'));
    expect(await card('ur')).toContain(d.ur.replace('{done}', '۳').replace('{total}', '۹'));
  });

  test('resumed → the line is gone again', async () => {
    await playThreeThenPause();
    await post(`/round/${tok()}/resume`);
    expect(draw().state.paused).toBe(false);
    expect(await card('en')).not.toContain('Continue another day.');
  });
});

describe('a closed round: no paused line', () => {
  test('paused, then the window ends → closed there; no card, no paused line', async () => {
    await playThreeThenPause();
    draw().window_end = iso(Date.now() - 1000);
    expect(await card('en')).toBe('');
    expect(draw().finished_at).toBeTruthy();
    expect(await (await get(`/page/${tok()}`)).text()).not.toContain('Continue another day.');
  });

  test('paused, then finished (finished_at set, state.paused still true) → no card', async () => {
    await playThreeThenPause();
    draw().finished_at = iso(Date.now());
    expect(await card('en')).toBe('');
    expect(await card('ur')).toBe('');
  });
});

describe('not paused → the card is byte-identical to the unchanged code (golden)', () => {
  test.each(['en', 'ur'])('not started (%s)', async (lang) => {
    expect(await card(lang)).toMatchSnapshot();
  });

  test.each(['en', 'ur'])('drawn, the window not open yet (%s)', async (lang) => {
    draw().window_start = iso(Date.now() + DAY);
    expect(await card(lang)).toMatchSnapshot();
  });

  test.each(['en', 'ur'])('running now (%s)', async (lang) => {
    await Round.start(TEACHER, { rng: () => 0.3 });
    const order = draw().state.order.map((p) => p.id);
    await post(`/round/${tok()}/next`, HOLD);
    await Round.childFinished(ROUND, order[0], 'run-0');
    await post(`/round/${tok()}/teacher`, HOLD);
    expect(await card(lang)).toMatchSnapshot();
  });

  test.each(['en', 'ur'])('paused, then resumed (%s)', async (lang) => {
    await playThreeThenPause();
    await post(`/round/${tok()}/resume`);
    expect(await card(lang)).toMatchSnapshot();
  });

  test('no draw → no card', async () => {
    DB.class_round_draws.length = 0;
    expect(await card('en')).toBe('');
  });
});
